{"hypotheses": [
  {
    "name": "Customer Momentum x Patent Innovation",
    "mechanism": "Firms with strong customer momentum and high patent-to-R&D ratios should both benefit from positive downstream demand and superior innovation, resulting in synergistic exposure to durable growth that is underpriced due to investor underappreciation of supply-chain and IP channel interaction. The composite outperforms as it captures both demand-pull and innovation-push effects, which are less likely to be simultaneously arbitraged.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "PatentsRD"},
        {"weight": -0.5, "primitive": "BetaTailRisk"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 42
  },
  {
    "name": "Governance Consistency and Deferred Revenue",
    "mechanism": "Stocks with consistently strong governance and rising deferred revenue should outperform, as disciplined managements are better at securing prepayments and long-term contracts that support forward earnings visibility. The interaction exploits a pricing error where the market underweights deferred revenue accruals except in well-governed firms, leading to unique alpha beyond either primitive.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 0.5, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Governance", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 38
  },
  {
    "name": "Analyst Underreaction to Real Asset Growth",
    "mechanism": "Firms with upward analyst revisions that also exhibit rapid growth in real estate holdings signal overlooked real asset expansion not fully incorporated into earnings forecasts. This composite exploits behavioral underreaction by sell-side analysts to non-core asset growth news, producing differentiated returns from either input alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": 0.5, "primitive": "realestate"},
        {"weight": -0.5, "primitive": "ShareIss1Y"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.62,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Operating Cashflow Surprise and Supply Chain Skew",
    "mechanism": "This factor combines positive cashflow-to-price shocks with contemporaneous supplier momentum. The rationale is that cashflow surprises made possible or confirmed by strong upstream supply signals are more persistent, while negative supply chain signals often precede cashflow disappointment. The interaction captures the informational synergy often missed by standalone signals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "cfp"},
        {"weight": 0.5, "primitive": "iomom_supp"},
        {"weight": -0.5, "primitive": "ReturnSkew"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "cfp", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.59,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Sin Stock Concentration with Deferred Tax",
    "mechanism": "Sin stocks with high deferred tax liabilities are doubly neglected: investors avoid them for ESG reasons, and deferred tax accounting is often misunderstood. This composite bets on excess return from the intersection of the sin premium and deferred tax underreaction, as both mechanisms are slow-moving and orthogonal, yielding a unique premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "sinAlgo"},
        {"weight": 0.5, "primitive": "ChTax"},
        {"weight": -0.5, "primitive": "VolSD"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"},
      {"type": "correlation", "primitive": "sinAlgo", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.66,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Organizational Capital x Forecast Dispersion",
    "mechanism": "Firms with high organizational capital (intangible know-how) but low analyst forecast dispersion are underappreciated because their intangible advantages are not yet recognized by sell-side analysts. The composite exploits the tendency for subsequent repricing as consensus converges around intangible value, a phenomenon not captured by each primitive individually.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "DelBreadth"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Credit Downgrade Resilience in High Intangible Firms",
    "mechanism": "Among firms with high intangibles, those that avoid credit rating downgrades outperform, as the market overestimates the impact of tangible asset coverage while underpricing the resilience of intangible-rich firms to credit events. The composite arbitrages this mispricing by blending intangible-adjusted value with credit event avoidance.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": -0.5, "primitive": "CredRatDG"},
        {"weight": 0.5, "primitive": "HerfAsset"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "CredRatDG", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.64,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Seasonal Industry Return with Active Shareholder Overlay",
    "mechanism": "Industry return seasonality effects are amplified when combined with signals of activist investor presence, as coordinated activism tends to unlock latent value in industries prone to cyclical repricing. The overlay ensures the premium is realized when both industry cycles and shareholder pressure coincide, a more robust alpha source than either alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomSeason"},
        {"weight": 0.5, "primitive": "Activism2"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mid", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 21
  }
]}
